XM11 N15 LABEL_NET_1 VDD VDD sky130_fd_pr__pfet_01v8 l={L_xm11} w={W_xm11}
XM31 OUT_N R_P OUT1 GND sky130_fd_pr__nfet_01v8 l={L_xm31} w={W_xm31}

* DC Sources
VVDD VDD 0 1.8
VLABEL LABEL_NET_1 0 0.9
* Set R_P high to enable output switches
VRP R_P 0 1.8
* Ground N14 to fix floating node extraction error (enables XM14 tail current)
VN14 N14 0 0

* Input Signal (Tied to both IN1 and IN2)
VIN IN 0 DC 0.9 AC 1 PULSE(0.1 1.7 10n 10n 10n 1u 2u)
R1 IN IN1 1m
R2 IN IN2 1m

* Load Capacitance (from paper)
CLOAD OUT1 0 30p
* Passive pull-down to compensate for disabled XM20 due to N14 grounding
RPD OUT1 0 20k

.control
  * 1. DC Operating Point for Power
  op
  let power = -i(VVDD) * 1.8
  print power

  * 2. AC Analysis for Bandwidth
  ac dec 10 1k 1G
  let gain_db = vdb(OUT1)
  meas ac gain_dc find gain_db at=1k
  meas ac bw_3db when gain_db=-3 fall=1

  * 3. Transient Analysis for Slew Rate and Swing
  tran 1n 3u
  meas tran trise trig v(OUT1) val=0.3 rise=1 targ v(OUT1) val=1.5 rise=1
  meas tran tfall trig v(OUT1) val=1.5 fall=1 targ v(OUT1) val=0.3 fall=1
  meas tran vmax max v(OUT1)
  meas tran vmin min v(OUT1)

  quit
.endc
.end

